SELECT o.type, o.path, o.off FROM obj o WHERE o.owner IN (SELECT addr FROM obj WHERE path IN ('/Script/Engine.KismetStringLibrary:ParseIntoArray','/Script/Engine.KismetStringLibrary:Concat_StrStr','/Script/Engine.KismetStringLibrary:Conv_StringToSoftClassReference','/Script/Sparta.SpartaSaveSubSystem:ResetSaveObjectByGuid','/Script/Sparta.SpartaSaveSubSystem:ResetSaveObjectByClass','/Script/Sparta.SpartaSaveSubSystem:GetSaveObjectByClassFromSlotIndex') ) ORDER BY o.line
